{
  "title": "The Rescue of Ashvale",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A weary band approaches the ruined royal city at dusk.",
      "visual_description": "Wide shot of three travelers cresting a hill overlooking a shattered skyline of broken spires and tattered banners, orange sunset behind them.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage"]
    },
    {
      "scene_number": 2,
      "caption": "Mira unrolls a brittle map of the fallen city.",
      "visual_description": "Close shot of a hand-drawn parchment map weighed down by stones, candle flickering, three faces leaning in around it.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage"]
    },
    {
      "scene_number": 3,
      "caption": "They slip past the cracked castle gates.",
      "visual_description": "Two enormous iron gates hang crooked on snapped hinges, vines crawling up the stonework, figures squeezing through the gap in silhouette.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage"]
    },
    {
      "scene_number": 4,
      "caption": "Frightened townspeople peek from a shuttered alley.",
      "visual_description": "Narrow cobbled alley with boarded windows; a mother and child peer through slats, eyes wide, lantern light spilling on wet stones.",
      "characters": ["Mira the Scout", "Hessa the Baker", "Little Tomm"]
    },
    {
      "scene_number": 5,
      "caption": "Hessa whispers that the princess is held in the north tower.",
      "visual_description": "Tight interior of a ruined bakery, flour-dusted counter, Hessa pointing a trembling finger toward a window framing a distant black tower.",
      "characters": ["Captain Wrenn", "Hessa the Baker", "Olen the Mage"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol marches through the square.",
      "visual_description": "Overhead angle of a cracked fountain plaza, six armored soldiers in red tabards crossing in formation, the heroes pressed flat against a column.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage", "Sergeant Korv"]
    },
    {
      "scene_number": 7,
      "caption": "Olen senses a curse curling around the tower.",
      "visual_description": "Olen kneeling on rooftop tiles, fingertips glowing faint blue, wisps of violet smoke spiraling toward a tall jagged spire in the distance.",
      "characters": ["Olen the Mage", "Mira the Scout"]
    },
    {
      "scene_number": 8,
      "caption": "Rumor of a dragon stirs the lower city.",
      "visual_description": "A crowded crooked tavern interior, drunk patrons gesturing wildly, a crude charcoal sketch of a winged beast pinned to the wall.",
      "characters": ["Captain Wrenn", "Brann the Drunk Herald", "Hessa the Baker"]
    },
    {
      "scene_number": 9,
      "caption": "They debate whether the dragon is real or a distraction.",
      "visual_description": "Three heroes huddled under a torn royal banner draped like a tent, faces lit by a single candle, expressions tense.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage"]
    },
    {
      "scene_number": 10,
      "caption": "Mira scales the outer wall of the cursed tower.",
      "visual_description": "Vertical composition, Mira climbing weathered black stone, rope coiled at her hip, gargoyles jutting from the masonry, moon behind her.",
      "characters": ["Mira the Scout"]
    },
    {
      "scene_number": 11,
      "caption": "A magic door bars the inner stair.",
      "visual_description": "Massive arched door carved with glowing runic spirals, pulsing pale green, Olen raising both palms while Wrenn watches sword drawn.",
      "characters": ["Captain Wrenn", "Olen the Mage"]
    },
    {
      "scene_number": 12,
      "caption": "Olen unbinds the runes with a whispered key.",
      "visual_description": "Close-up of glowing runes dissolving into floating embers, Olen's face half-lit gold, sweat on his brow.",
      "characters": ["Olen the Mage"]
    },
    {
      "scene_number": 13,
      "caption": "They find Princess Liraen in the cell at the top.",
      "visual_description": "Round tower room with a single barred window, the princess in a torn blue gown rising from a stone bench, chains at her wrists.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Princess Liraen"]
    },
    {
      "scene_number": 14,
      "caption": "Sergeant Korv discovers the broken door and sounds the alarm.",
      "visual_description": "Korv on the stair landing, helmet under one arm, raising a curved horn to his lips, torchlight flaring red on his armor.",
      "characters": ["Sergeant Korv"]
    },
    {
      "scene_number": 15,
      "caption": "The group flees down spiraling stairs as patrols close in.",
      "visual_description": "Dynamic diagonal shot of a spiral staircase, four figures rushing down, shadows of pursuing soldiers cast huge on the curving wall.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage", "Princess Liraen"]
    },
    {
      "scene_number": 16,
      "caption": "They burst into the plaza and Brann points to a hidden path.",
      "visual_description": "Rain-slicked plaza at night, Brann staggering forward with a lantern, pointing toward a narrow gap between two collapsed buildings.",
      "characters": ["Captain Wrenn", "Princess Liraen", "Brann the Drunk Herald", "Olen the Mage"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the crumbling stone bridge.",
      "visual_description": "Long arched bridge over a black ravine, stones falling away behind running feet, mist rising from below, torches bobbing in pursuit.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage", "Princess Liraen", "Sergeant Korv"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far ridge, they look back at the burning city.",
      "visual_description": "Four silhouettes on a grassy cliff at dawn, royal banner fragment in Wrenn's hand fluttering, distant city glowing with fires and faint dragon-shaped smoke.",
      "characters": ["Captain Wrenn", "Mira the Scout", "Olen the Mage", "Princess Liraen"]
    }
  ]
}

